def find_files_recursive(directory, name_patterns, max_depth=10):
    found = []
    for root, dirs, files in os.walk(directory):
        # Track depth
        depth = root.replace(directory, '').count(os.sep)
        if depth > max_depth:
            continue
        for f in files:
            for pattern in name_patterns:
