def transform(grid):
    rows, cols = len(grid), len(grid[0])
    output = [[val for val in row] for row in grid]  # Start as copy

    # Pattern based on test input 8-shape structure
    # Block 1: rows 3-5, cols 2-5 → split left(2-3)=2, right(4-5)=4
    # Block 2: rows 6-9, cols 6-13 → full=3
    # Block 3: rows 10-13, cols 2-9 → split left(2-5)=4, right(6-9)=1

    for r in range(rows):
        for c in range(cols):
